from __future__ import annotations

import base64
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
BACKUP_SUFFIX = f".bak_dados_{datetime.now().strftime('%Y%m%d_%H%M%S')}"

ARQUIVOS = {
    "backend/app/services/dados_service.py": '',
}


def salvar_arquivo(relativo: str, conteudo_b64: str) -> None:
    destino = ROOT / relativo
    destino.parent.mkdir(parents=True, exist_ok=True)

    if destino.exists():
        backup = destino.with_name(destino.name + BACKUP_SUFFIX)
        backup.write_bytes(destino.read_bytes())
        print(f"Backup: {backup}")

    destino.write_bytes(base64.b64decode(conteudo_b64))
    print(f"Atualizado: {destino}")


def main() -> None:
    if not (ROOT / "backend" / "app").exists():
        raise SystemExit(
            "Coloque instalar_elenco_completo.py na raiz do projeto central-do-galo."
        )

    for relativo, conteudo_b64 in ARQUIVOS.items():
        salvar_arquivo(relativo, conteudo_b64)

    print()
    print("Correção aplicada.")
    print("- erro HTTP 500 do endpoint /api/dados/filtros corrigido")
    print("- nenhuma nova coleta do SofaScore é necessária")
    print()
    print("Reinicie o backend e atualize a página /dados.")


if __name__ == "__main__":
    main()
